SELECT * FROM sys_role WHERE role_id IN
#{id}
ORDER BY role_id FOR UPDATE


SELECT COUNT(*) FROM sys_user u
JOIN sys_user_role ur ON ur.user_id = u.user_id AND ur.role_id = 1
JOIN sys_role r ON r.role_id = ur.role_id AND r.role_code = 'admin' AND r.status = 1 AND r.data_scope = 'ALL'
WHERE u.status = 1 AND (
SELECT COUNT(*) FROM sys_role_permission rp
JOIN sys_permission p ON p.permission_id = rp.permission_id AND p.status = 1
WHERE rp.role_id = 1 AND p.permission_code IN
#{code}
) = #{requiredCount}
